import React from 'react';
import { Navbar, Container, Dropdown } from 'react-bootstrap';
import Avatar from 'react-avatar';

const Header = ({ username, isloggedin = false }) => {

    const handleLogout = () => {
        // setIsLoggedIn(false);
        localStorage.removeItem("token");
        window.location.href = '/signin';
    };
    return (
        <Navbar bg="dark" variant="dark" className="py-1 px-3">
            <Container fluid>
                {/* App Name / Logo */}
                <Navbar.Brand className="me-auto">
                    <div className='d-flex align-items-center'>
                        <div class="loader2" style={{ float: 'left' }} ></div>
                        <strong className='px-3'> Chat App </strong>
                    </div>
                    <div className='d-flex align-items-center'>
                        <div className="loader"></div>
                        <span style={{ float: 'left',  }}>Hello</span>
                    </div>
                </Navbar.Brand>

                {isloggedin && <>
                    {/* User Dropdown */}
                    <div className="d-flex align-items-center">
                        <Dropdown align="end">
                            <Dropdown.Toggle variant="dark" id="user-dropdown" className="rounded p-2">
                                <Avatar
                                    name={username}
                                    size="32"
                                    maxInitials='2'
                                    round={true}
                                    color="#007bff"     // Background color
                                    fgColor="#fff"      // Text color
                                    className="me-2"
                                />
                                <span className="fw-bold">{username}</span>
                            </Dropdown.Toggle>

                            <Dropdown.Menu>
                                <Dropdown.Item onClick={handleLogout} className="text-danger">
                                    Logout
                                </Dropdown.Item>
                            </Dropdown.Menu>
                        </Dropdown>
                    </div>
                </>
                }

            </Container>

        </Navbar>

    );
}

export default Header;
